/* Private columns stay private, and server owned columns stay the server's. Until now anyone with the public key could read every column of profiles and creators: every account's email and role, home address fields, spam flags and time zone, and every creator's Stripe ids, plan, payout settings, statement descriptor and ban reason. Visitors and signed in users now read only the public columns of those two tables (name, handle, photo, bio, links, the storefront's settings, the support email a creator publishes); the server reads everything as before, and the app reads a person's own private columns through the server. public.storelib_share_public_columns() does the granting from one list of private columns (public.storelib_private_columns), so a column added later is public unless it is on that list; run it again after adding a column to either table (the check after says whether every column is shared or listed). It also rebuilds public.creators_public and public.profiles_public, the same tables with the public columns only, read with the reader's own rights, for pages that want every public column. Signed in users can no longer change what only the server may: a creator's Stripe account, plan, payouts switch, ban and review counts; a profile's role, spam state and official, verified and staff marks. The trigger keeps the old value on an update and the column's default on an insert, and profiles.email always follows the sign in email. Safe to run again. */
CREATE OR REPLACE FUNCTION public.storelib_private_columns(p_table text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $f$ SELECT CASE p_table WHEN 'creators' THEN ARRAY['stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'payout_currency', 'payout_schedule', 'payout_threshold', 'instant_payouts_enabled', 'banned_reason', 'statement_descriptor', 'first_sale_email_sent'] WHEN 'profiles' THEN ARRAY['email', 'role', 'spam_state', 'spam_score', 'personalized_recommendations', 'timezone', 'push_messages_enabled', 'push_preview_enabled', 'first_name', 'last_name', 'address_line1', 'address_line2', 'city', 'state', 'postal_code', 'country', 'phone', 'date_of_birth', 'tax_id'] ELSE ARRAY[]::text[] END $f$;
CREATE OR REPLACE FUNCTION public.storelib_share_public_columns() RETURNS void LANGUAGE plpgsql AS $f$ DECLARE t text; col record; cols text; BEGIN FOREACH t IN ARRAY ARRAY['creators','profiles'] LOOP IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF; EXECUTE format('REVOKE SELECT ON public.%I FROM anon, authenticated', t); FOR col IN SELECT a.attname FROM pg_attribute a WHERE a.attrelid = ('public.' || t)::regclass AND a.attnum > 0 AND NOT a.attisdropped LOOP IF col.attname::text = ANY (public.storelib_private_columns(t)) THEN EXECUTE format('REVOKE SELECT (%I) ON public.%I FROM anon, authenticated', col.attname, t); ELSE EXECUTE format('GRANT SELECT (%I) ON public.%I TO anon, authenticated', col.attname, t); END IF; END LOOP; SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY a.attnum) INTO cols FROM pg_attribute a WHERE a.attrelid = ('public.' || t)::regclass AND a.attnum > 0 AND NOT a.attisdropped AND NOT (a.attname::text = ANY (public.storelib_private_columns(t))); EXECUTE format('DROP VIEW IF EXISTS public.%I', t || '_public'); EXECUTE format('CREATE VIEW public.%I WITH (security_invoker = true) AS SELECT %s FROM public.%I', t || '_public', cols, t); EXECUTE format('GRANT SELECT ON public.%I TO anon, authenticated, service_role', t || '_public'); END LOOP; END $f$;
REVOKE ALL ON FUNCTION public.storelib_share_public_columns() FROM PUBLIC, anon, authenticated;
SELECT public.storelib_share_public_columns();
CREATE OR REPLACE FUNCTION public.storelib_sign_in_email(p_user uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT u.email::text FROM auth.users u WHERE u.id = p_user AND p_user = auth.uid() $f$;
REVOKE ALL ON FUNCTION public.storelib_sign_in_email(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.storelib_sign_in_email(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.storelib_keep_server_columns() RETURNS trigger LANGUAGE plpgsql AS $f$ DECLARE col text; newj jsonb; oldj jsonb; expr text; v jsonb; mail text; BEGIN IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF; newj := to_jsonb(NEW); IF TG_OP = 'UPDATE' THEN oldj := to_jsonb(OLD); END IF; FOREACH col IN ARRAY TG_ARGV LOOP IF NOT (newj ? col) THEN CONTINUE; END IF; IF TG_OP = 'UPDATE' THEN newj := jsonb_set(newj, ARRAY[col], coalesce(oldj -> col, 'null'::jsonb)); ELSIF col <> 'user_id' THEN expr := NULL; SELECT pg_get_expr(d.adbin, d.adrelid) INTO expr FROM pg_attribute a JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE a.attrelid = TG_RELID AND a.attname = col; IF expr IS NULL THEN v := 'null'::jsonb; ELSE EXECUTE 'SELECT to_jsonb(' || expr || ')' INTO v; END IF; newj := jsonb_set(newj, ARRAY[col], v); END IF; END LOOP; IF TG_TABLE_NAME = 'profiles' AND (newj ? 'email') THEN mail := public.storelib_sign_in_email((newj ->> 'id')::uuid); IF mail IS NOT NULL THEN newj := jsonb_set(newj, ARRAY['email'], to_jsonb(mail)); ELSIF TG_OP = 'UPDATE' THEN newj := jsonb_set(newj, ARRAY['email'], coalesce(oldj -> 'email', 'null'::jsonb)); END IF; END IF; NEW := jsonb_populate_record(NEW, newj); RETURN NEW; END $f$;
DO $do$ BEGIN IF to_regclass('public.creators') IS NOT NULL THEN DROP TRIGGER IF EXISTS creators_keep_server_columns ON public.creators; CREATE TRIGGER creators_keep_server_columns BEFORE INSERT OR UPDATE ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('user_id', 'stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'charges_enabled', 'payouts_enabled', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'banned_at', 'banned_reason', 'first_sale_email_sent', 'reviews_average', 'reviews_count', 'views', 'featured'); END IF; IF to_regclass('public.profiles') IS NOT NULL THEN DROP TRIGGER IF EXISTS profiles_keep_server_columns ON public.profiles; CREATE TRIGGER profiles_keep_server_columns BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('role', 'spam_state', 'spam_score', 'is_official', 'is_verified', 'is_staff'); END IF; END $do$;
notify pgrst, 'reload schema';
